/// <summary>
/// The MobDocumentNodes class contains a hierarchy of nodes, that can be exported to XML.
/// </summary>
class MobDocumentNodes extends TFMDocumentNodes
{

}

Method.Source:
Public static MobDocumentNodes Construct(str _root)
{
    return new MobDocumentNodes(_root);
}

protected void new(str _rootName)
{
    MobDocumentNode root = MobDocumentNode::Construct(0,null, this);
    root.parmName(_rootName);
    nodes = new Map(Types::int64, Types::Class);
    rootLevelNodes = new Set(Types::Int64);
    rootLevelNodes.add(0);
    nodes.insert(0,root);
    //return root;
}
